<section class="container section auth-layout"><div class="auth-aside"><p class="eyebrow">IDEAS QUE TOMAN FORMA</p><h2>Algo único.<br>Algo tuyo.</h2><p>Guardá tus pedidos y acompañá cada paso, desde la idea hasta tus manos.</p><span class="auth-star" aria-hidden="true"><span class="brand-symbol" aria-hidden="true"></span></span></div><div class="form-panel"><p class="eyebrow"><?= $authPath==='/registro'?'SUMATE A FILOLUX':'TU ESPACIO' ?></p><h1><?= e($title) ?></h1><?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif ?><form method="post"><?= csrf() ?><?php if($authPath==='/registro'): ?><label>Tu nombre<input name="name" autocomplete="name" maxlength="120" value="<?= e($_POST['name']??'') ?>" required></label><?php endif ?><?php if($authPath==='/restablecer'): ?><input name="email" type="hidden" value="<?= e($_GET['email']??$_POST['email']??'') ?>"><input name="token" type="hidden" value="<?= e($_GET['token']??$_POST['token']??'') ?>"><?php else: ?><label><?= $authPath==='/login'?'Usuario o correo electrónico':'Correo electrónico' ?><input name="email" type="<?= $authPath==='/login'?'text':'email' ?>" autocomplete="<?= $authPath==='/login'?'username':'email' ?>" maxlength="190" value="<?= e($_POST['email']??'') ?>" required></label><?php endif ?><?php if($authPath!=='/recuperar'): ?><label>Contraseña<input name="password" type="password" autocomplete="<?= $authPath==='/login'?'current-password':'new-password' ?>" <?= $authPath==='/login'?'':'minlength="10" maxlength="72"' ?> required></label><?php if($authPath!=='/login'): ?><p class="microcopy">Usá entre 10 y 72 caracteres.</p><?php endif ?><?php endif ?><button class="btn full"><?= ['/login'=>'Ingresar','/registro'=>'Crear mi cuenta','/recuperar'=>'Enviar enlace','/restablecer'=>'Guardar contraseña'][$authPath] ?> ↗</button></form><div class="auth-links"><?php if($authPath==='/login'): ?><a href="/recuperar">Olvidé mi contraseña</a><p>¿Es tu primera vez? <a href="/registro">Creá tu cuenta ↗</a></p><?php else: ?><a href="/login">Ya tengo cuenta. Ingresar ↗</a><?php endif ?></div></div></section>
